import React, { useState, useEffect, useContext } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Grid,
  Chip,
  LinearProgress,
  Alert,
  IconButton,
  Tooltip,
  Paper,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
} from '@mui/material';
import {
  PlayArrow,
  Pause,
  Stop,
  Refresh,
  Timeline,
  Speed,
  Security,
  TrendingUp,
  CheckCircle,
  Warning,
  Info,
  PlayCircleOutline,
  PauseCircleOutline,
  StopCircleOutline,
} from '@mui/icons-material';
import { motion, AnimatePresence } from 'framer-motion';
import { useDashboardContext } from '../context/DashboardContext';

const EICDemo = () => {
  const { socket, isConnected } = useDashboardContext();
  const [demoStatus, setDemoStatus] = useState('idle'); // idle, running, paused, completed
  const [currentStep, setCurrentStep] = useState(0);
  const [totalSteps, setTotalSteps] = useState(7);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [demoData, setDemoData] = useState({});
  const [vehicleStatus, setVehicleStatus] = useState({});
  const [motionData, setMotionData] = useState({});
  const [securityAlerts, setSecurityAlerts] = useState([]);
  const [performanceMetrics, setPerformanceMetrics] = useState({});

  const [demoSteps, setDemoSteps] = useState([
    {
      id: 1,
      title: 'Demo Start',
      description: 'Vehicle Discovery & Reservation',
      icon: '🚀',
      duration: 5,
      status: 'pending'
    },
    {
      id: 2,
      title: 'Ride Initiation',
      description: 'User starts journey',
      icon: '🚗',
      duration: 8,
      status: 'pending'
    },
    {
      id: 3,
      title: 'Smart Pause',
      description: 'User stops for coffee (legitimate pause)',
      icon: '⏸️',
      duration: 12,
      status: 'pending'
    },
    {
      id: 4,
      title: 'Motion Detection',
      description: 'System analyzes movement patterns',
      icon: '🔍',
      duration: 10,
      status: 'pending'
    },
    {
      id: 5,
      title: 'Auto-Resume',
      description: 'Motion detected, ride continues automatically',
      icon: '▶️',
      duration: 8,
      status: 'pending'
    },
    {
      id: 6,
      title: 'Security Demo',
      description: 'Unauthorized movement detection',
      icon: '🚨',
      duration: 10,
      status: 'pending'
    },
    {
      id: 7,
      title: 'Demo Complete',
      description: 'Innovation summary and metrics',
      icon: '✅',
      duration: 7,
      status: 'pending'
    }
  ]);

  useEffect(() => {
    if (!socket) return;

    // Listen for EIC demo events
    socket.on('eic-demo-event', (data) => {
      console.log('🎬 EIC Demo event received:', data);
      handleDemoEvent(data);
    });

    // Listen for telemetry updates
    socket.on('telemetry-update', (data) => {
      if (data.vehicleId && data.vehicleId.includes('eic_demo')) {
        setVehicleStatus(data);
      }
    });

    return () => {
      socket.off('eic-demo-event');
      socket.off('telemetry-update');
    };
  }, [socket]);

  useEffect(() => {
    let interval;
    if (demoStatus === 'running') {
      interval = setInterval(() => {
        setElapsedTime(prev => prev + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [demoStatus]);

  const handleDemoEvent = (data) => {
    const { type, step, data: eventData } = data;

    switch (type) {
      case 'demo-started':
        setDemoStatus('running');
        setCurrentStep(1);
        setDemoData(eventData);
        updateStepStatus(1, 'active');
        break;
      case 'ride-initiated':
        setCurrentStep(2);
        updateStepStatus(1, 'completed');
        updateStepStatus(2, 'active');
        break;
      case 'smart-pause-triggered':
        setCurrentStep(3);
        updateStepStatus(2, 'completed');
        updateStepStatus(3, 'active');
        setMotionData(eventData);
        break;
      case 'motion-detection-active':
        setCurrentStep(4);
        updateStepStatus(3, 'completed');
        updateStepStatus(4, 'active');
        break;
      case 'auto-resume-triggered':
        setCurrentStep(5);
        updateStepStatus(4, 'completed');
        updateStepStatus(5, 'active');
        break;
      case 'security-alert':
        setCurrentStep(6);
        updateStepStatus(5, 'completed');
        updateStepStatus(6, 'active');
        setSecurityAlerts(prev => [...prev, eventData]);
        break;
      case 'demo-completed':
        setDemoStatus('completed');
        setCurrentStep(7);
        updateStepStatus(6, 'completed');
        updateStepStatus(7, 'completed');
        setPerformanceMetrics(eventData);
        break;
      default:
        break;
    }
  };

  const updateStepStatus = (stepNumber, status) => {
    setDemoSteps(prev => prev.map(step => 
      step.id === stepNumber 
        ? { ...step, status }
        : step.status === 'active' 
          ? { ...step, status: 'pending' }
          : step
    ));
  };

  const startDemo = async () => {
    try {
      console.log('🚀 Starting EIC Demo...');

      // Add EIC demo scenario
      console.log('📝 Adding EIC demo scenario...');
      const scenarioResponse = await fetch('http://localhost:3002/api/scenarios', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: 'eic-demo',
          config: { type: 'eic-demo' }
        })
      });

      if (!scenarioResponse.ok) {
        throw new Error(`Failed to add scenario: ${scenarioResponse.status}`);
      }

      const scenarioResult = await scenarioResponse.json();
      console.log('✅ Scenario added:', scenarioResult);

      // Start the demo
      console.log('▶️ Starting EIC demo scenario...');
      const startResponse = await fetch('http://localhost:3002/api/scenarios/eic-demo/start', {
        method: 'POST'
      });

      if (!startResponse.ok) {
        throw new Error(`Failed to start scenario: ${startResponse.status}`);
      }

      const startResult = await startResponse.json();
      console.log('✅ Scenario started:', startResult);

      // Add some vehicles for the demo
      console.log('🚗 Adding demo vehicles...');
      const vehiclesResponse = await fetch('http://localhost:3002/api/vehicles', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          count: 3,
          scenario: 'eic-demo'
        })
      });

      if (vehiclesResponse.ok) {
        const vehiclesResult = await vehiclesResponse.json();
        console.log('✅ Vehicles added:', vehiclesResult);
      }

      setDemoStatus('running');
      setElapsedTime(0);
      setCurrentStep(1);
      setDemoData({});
      setVehicleStatus({});
      setMotionData({});
      setSecurityAlerts([]);
      setPerformanceMetrics({});

      // Reset all steps
      setDemoSteps(prev => prev.map(step => ({ ...step, status: 'pending' })));
      updateStepStatus(1, 'active');

      console.log('🎉 EIC Demo started successfully!');

    } catch (error) {
      console.error('❌ Error starting demo:', error);
      alert(`Failed to start demo: ${error.message}`);
    }
  };

  const pauseDemo = () => {
    setDemoStatus('paused');
  };

  const resumeDemo = () => {
    setDemoStatus('running');
  };

  const stopDemo = () => {
    setDemoStatus('idle');
    setElapsedTime(0);
    setCurrentStep(0);
    setDemoData({});
    setVehicleStatus({});
    setMotionData({});
    setSecurityAlerts([]);
    setPerformanceMetrics({});
    setDemoSteps(prev => prev.map(step => ({ ...step, status: 'pending' })));
  };

  const resetDemo = () => {
    stopDemo();
    startDemo();
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getStepColor = (status) => {
    switch (status) {
      case 'completed': return 'success';
      case 'active': return 'primary';
      case 'pending': return 'default';
      default: return 'default';
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h3" component="h1" gutterBottom sx={{ color: 'primary.main' }}>
          🎬 EIC Accelerator Demo
        </Typography>
        <Typography variant="h6" color="text.secondary" gutterBottom>
          Smart Pause & Resume Innovation Demonstration
        </Typography>
        <Typography variant="body1" color="text.secondary">
          €2.5M Deep-Tech Funding Program - Complete Innovation Showcase in 60 Seconds
        </Typography>
      </Box>

      {/* Connection Status */}
      <Alert 
        severity={isConnected ? 'success' : 'error'} 
        sx={{ mb: 3 }}
        action={
          <Button 
            color="inherit" 
            size="small"
            onClick={() => window.location.reload()}
          >
            Reconnect
          </Button>
        }
      >
        {isConnected ? 'Connected to Vehicle Simulator' : 'Disconnected from Vehicle Simulator'}
      </Alert>

      {/* Demo Controls */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
            <Typography variant="h6">Demo Controls</Typography>
            <Chip 
              label={demoStatus.toUpperCase()} 
              color={demoStatus === 'running' ? 'success' : demoStatus === 'paused' ? 'warning' : 'default'}
              variant="outlined"
            />
          </Box>

          <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
            <Button
              variant="contained"
              color="success"
              startIcon={<PlayArrow />}
              onClick={startDemo}
              disabled={demoStatus === 'running' || !isConnected}
            >
              Start Demo
            </Button>

            <Button
              variant="contained"
              color="warning"
              startIcon={<Pause />}
              onClick={pauseDemo}
              disabled={demoStatus !== 'running'}
            >
              Pause
            </Button>

            <Button
              variant="contained"
              color="info"
              startIcon={<PlayCircleOutline />}
              onClick={resumeDemo}
              disabled={demoStatus !== 'paused'}
            >
              Resume
            </Button>

            <Button
              variant="contained"
              color="error"
              startIcon={<Stop />}
              onClick={stopDemo}
              disabled={demoStatus === 'idle'}
            >
              Stop
            </Button>

            <Button
              variant="outlined"
              startIcon={<Refresh />}
              onClick={resetDemo}
              disabled={!isConnected}
            >
              Reset
            </Button>
          </Box>

          {/* Progress Bar */}
          {demoStatus !== 'idle' && (
            <Box sx={{ mt: 2 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="body2">
                  Progress: {currentStep}/{totalSteps} steps
                </Typography>
                <Typography variant="body2">
                  Time: {formatTime(elapsedTime)} / 01:00
                </Typography>
              </Box>
              <LinearProgress 
                variant="determinate" 
                value={(currentStep / totalSteps) * 100}
                sx={{ height: 8, borderRadius: 4 }}
              />
            </Box>
          )}
        </CardContent>
      </Card>

      <Grid container spacing={3}>
        {/* Demo Steps */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Demo Steps
              </Typography>
              <List>
                {demoSteps.map((step) => (
                  <ListItem key={step.id} sx={{ px: 0 }}>
                    <ListItemIcon>
                      <Box sx={{ fontSize: '1.5rem' }}>{step.icon}</Box>
                    </ListItemIcon>
                    <ListItemText
                      primary={
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <Typography variant="body1" fontWeight="medium">
                            {step.title}
                          </Typography>
                          <Chip 
                            label={step.status} 
                            size="small" 
                            color={getStepColor(step.status)}
                            variant={step.status === 'active' ? 'filled' : 'outlined'}
                          />
                        </Box>
                      }
                      secondary={
                        <Box>
                          <Typography variant="body2" color="text.secondary">
                            {step.description}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            Duration: {step.duration}s
                          </Typography>
                        </Box>
                      }
                    />
                  </ListItem>
                ))}
              </List>
            </CardContent>
          </Card>
        </Grid>

        {/* Real-time Data */}
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Real-time Data
              </Typography>

              {/* Vehicle Status */}
              {vehicleStatus.vehicleId && (
                <Box sx={{ mb: 2 }}>
                  <Typography variant="subtitle2" color="primary" gutterBottom>
                    Vehicle Status
                  </Typography>
                  <Grid container spacing={1}>
                    <Grid item xs={6}>
                      <Typography variant="body2">ID: {vehicleStatus.vehicleId}</Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2">Speed: {vehicleStatus.speed || 0} km/h</Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2">Battery: {vehicleStatus.battery || 0}%</Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2">Status: {vehicleStatus.status || 'unknown'}</Typography>
                    </Grid>
                  </Grid>
                </Box>
              )}

              {/* Motion Data */}
              {motionData.motionAnalysis && (
                <Box sx={{ mb: 2 }}>
                  <Typography variant="subtitle2" color="primary" gutterBottom>
                    Motion Analysis
                  </Typography>
                  <Grid container spacing={1}>
                    <Grid item xs={6}>
                      <Typography variant="body2">Speed: {motionData.motionAnalysis.speed} km/h</Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2">Acceleration: {motionData.motionAnalysis.acceleration} m/s²</Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2">Type: {motionData.motionAnalysis.motionType}</Typography>
                    </Grid>
                    <Grid item xs={6}>
                      <Typography variant="body2">Confidence: {Math.round(motionData.motionAnalysis.confidence * 100)}%</Typography>
                    </Grid>
                  </Grid>
                </Box>
              )}

              {/* Security Alerts */}
              {securityAlerts.length > 0 && (
                <Box>
                  <Typography variant="subtitle2" color="error" gutterBottom>
                    Security Alerts
                  </Typography>
                  {securityAlerts.map((alert, index) => (
                    <Alert key={index} severity="warning" sx={{ mb: 1 }}>
                      {alert.securityEvent}
                    </Alert>
                  ))}
                </Box>
              )}
            </CardContent>
          </Card>
        </Grid>

        {/* Innovation Highlights */}
        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                🚀 Innovation Highlights
              </Typography>
              <Grid container spacing={2}>
                <Grid item xs={12} md={3}>
                  <Paper sx={{ p: 2, textAlign: 'center', bgcolor: 'primary.dark' }}>
                    <Speed sx={{ fontSize: 40, color: 'white', mb: 1 }} />
                    <Typography variant="h6" color="white">Smart Pause</Typography>
                    <Typography variant="body2" color="white">
                      Revolutionary 10-minute pause system
                    </Typography>
                  </Paper>
                </Grid>
                <Grid item xs={12} md={3}>
                  <Paper sx={{ p: 2, textAlign: 'center', bgcolor: 'secondary.dark' }}>
                    <Timeline sx={{ fontSize: 40, color: 'white', mb: 1 }} />
                    <Typography variant="h6" color="white">Motion Detection</Typography>
                    <Typography variant="body2" color="white">
                      AI-powered pattern recognition
                    </Typography>
                  </Paper>
                </Grid>
                <Grid item xs={12} md={3}>
                  <Paper sx={{ p: 2, textAlign: 'center', bgcolor: 'success.dark' }}>
                    <TrendingUp sx={{ fontSize: 40, color: 'white', mb: 1 }} />
                    <Typography variant="h6" color="white">Auto-Resume</Typography>
                    <Typography variant="body2" color="white">
                      Automatic ride continuation
                    </Typography>
                  </Paper>
                </Grid>
                <Grid item xs={12} md={3}>
                  <Paper sx={{ p: 2, textAlign: 'center', bgcolor: 'warning.dark' }}>
                    <Security sx={{ fontSize: 40, color: 'white', mb: 1 }} />
                    <Typography variant="h6" color="white">Theft Prevention</Typography>
                    <Typography variant="body2" color="white">
                      Real-time security monitoring
                    </Typography>
                  </Paper>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>

        {/* Performance Metrics */}
        {demoStatus === 'completed' && performanceMetrics.technicalMetrics && (
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  📊 Demo Performance Metrics
                </Typography>
                <Grid container spacing={3}>
                  <Grid item xs={12} md={4}>
                    <Typography variant="subtitle1" color="primary" gutterBottom>
                      Technical Excellence
                    </Typography>
                    <List dense>
                      {Object.entries(performanceMetrics.technicalMetrics).map(([key, value]) => (
                        <ListItem key={key} sx={{ px: 0 }}>
                          <ListItemIcon>
                            <CheckCircle color="success" />
                          </ListItemIcon>
                          <ListItemText
                            primary={key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}
                            secondary={value}
                          />
                        </ListItem>
                      ))}
                    </List>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Typography variant="subtitle1" color="secondary" gutterBottom>
                      Business Value
                    </Typography>
                    <List dense>
                      {Object.entries(performanceMetrics.businessValue).map(([key, value]) => (
                        <ListItem key={key} sx={{ px: 0 }}>
                          <ListItemIcon>
                            <TrendingUp color="secondary" />
                          </ListItemIcon>
                          <ListItemText
                            primary={key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}
                            secondary={value}
                          />
                        </ListItem>
                      ))}
                    </List>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Typography variant="subtitle1" color="success" gutterBottom>
                      EIC Accelerator Ready
                    </Typography>
                    <List dense>
                      {performanceMetrics.innovationPoints?.map((point, index) => (
                        <ListItem key={index} sx={{ px: 0 }}>
                          <ListItemIcon>
                            <CheckCircle color="success" />
                          </ListItemIcon>
                          <ListItemText primary={point} />
                        </ListItem>
                      ))}
                    </List>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        )}
      </Grid>
    </Box>
  );
};

export default EICDemo;
